ga0R(){return"\u0646\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641"},
gHl(){return"\u0646\u0642\u0644 \u0644\u0644\u0623\u0639\u0644\u0649 (\u064a\u0638\u0647\u0631 \u0623\u0648\u0644\u0627\u064b \u0641\u064a \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u062d\u0627\u0644\u0629)"},
gHk(){return"\u0646\u0642\u0644 \u0644\u0644\u0623\u0633\u0641\u0644"},
ga1j(){return"\u0627\u0644\u0627\u0633\u0645"},
ga1g(){return"\u0627\u0644\u0644\u0648\u0646 (\u0647\u064a\u0643\u0633\u060c \u0645\u062b\u0627\u0644: FFB8763F)"},
ga_K(){return"\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
gH9(){return"\u0625\u0636\u0627\u0641\u0629 \u0646\u0648\u0639 \u062d\u0627\u0644\u0629"},
ga08(){return"\u062a\u0639\u062f\u064a\u0644 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629"},
