gKV(){return"\u0632\u0645\u0627\u0646\u06ce \u0628\u06c6\u062a\u06cc"},
gahq(){return"\u0646\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u0627 \u0642\u06d5\u0631\u0632\u06ce \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646"},
gahr(){return"\u062a\u0627\u0628\u0627 \xab\u062d\u0633\u0627\u0628\xbb \u0628\u06c6 \u067e\u06d5\u0695\u06ce\u0646 \u0628\u06c6\u062a\u06cc \u0632\u06ce\u062f\u06d5 \u062f\u06a9\u06d5\u062a\u060c \u06a9\u0648 \u0642\u06d5\u0631\u0632\u06ce \u0645\u0627\u06cc \u06cc\u06ce \u0647\u06d5\u0631 \u062f\u06a9\u062a\u06c6\u0631\u06d5\u06a9\u06cc \u0628\u06c6 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u0646\u06cc\u0634\u0627\u0646 \u062f\u062f\u06d5\u062a (\u06a9\u06c6\u06cc\u0627 \u06a9\u06d5\u0634\u0641\u0627 \u062d\u0633\u0627\u0628\u06ce \u062f\u06a9\u062a\u06c6\u0631\u06cc)."},
